//! Mutation P32: lineage-aware evolution candidate integrity contracts.
use bioprism_foundation::{PRECLINICAL_BOUNDARY,RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize,Serialize};
use serde_json::{json,Value};
use std::collections::BTreeSet;
use thiserror::Error;
pub const BOUNDARY:&str=PRECLINICAL_BOUNDARY;
pub const CONTENT_TYPE:&str="application/vnd.aurora.mutation.evolution-integrity-card-1+json";
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct MutationCandidate4{pub mutation_id:String,pub parent_id:String,pub digest:String,pub effect_class:String,pub evidence_state:String,pub local:bool,pub aggregate_only:bool}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct EvolutionRequest4{pub schema_version:String,pub request_id:String,pub purpose:String,pub candidates:Vec<MutationCandidate4>,pub required_mutation_order:Vec<String>,pub replay_identity:String,pub policy_allowed:bool,pub protected_closure:bool,pub signed_manifest:bool,pub raw_data_local:bool,pub aggregate_only:bool,pub adversarial_events:Vec<String>,pub mutation_budget:usize,pub boundary:String}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct EvolutionArtifact4{pub artifact_id:String,pub content_type:String,pub content_hash:String,pub semantic_loss:Vec<String>,pub evidence_digests:Vec<String>,pub boundary:String}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct EvolutionCard7{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub request_id:String,pub purpose:String,pub disposition:String,pub mutation_order:Vec<String>,pub accepted_order:Vec<String>,pub rejected_order:Vec<String>,pub unknown_order:Vec<String>,pub omitted_order:Vec<String>,pub parent_order:Vec<String>,pub effect_order:Vec<String>,pub lineage_order:Vec<String>,pub replay_identity:String,pub closure_digest:String,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String,pub effect_receipts:Vec<String>,pub artifact:EvolutionArtifact4}
#[derive(Debug,Error)] pub enum EvolutionIntegrityError{#[error("evolution integrity input is invalid: {0}")] Invalid(String),#[error("evolution integrity digest failed: {0}")] Digest(String)}
fn digest(v:&str)->bool{v.len()==64&&v.bytes().all(|b|b.is_ascii_hexdigit())}fn canonical(v:&[String])->bool{v.windows(2).all(|w|w[0]<w[1])}fn invalid(v:impl Into<String>)->EvolutionIntegrityError{EvolutionIntegrityError::Invalid(v.into())}
pub fn manifest(feature_id:&str,contract_version:&str,scale:&str,mode:&str)->Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":feature_id,"version":contract_version,"owner_crate":"mutation","consumers":["metamorphic planner","lineage explorer","analysis runtime","research workbench"],"behavior":format!("qualify lineage-aware mutation candidates at {scale} ({mode})"),"value":"prevents orphaned, untyped, unproven, or unsafe mutation candidates from driving preclinical research workflows","input_schema":"EvolutionRequest4@1","output_schema":"EvolutionCard7@1","effects":["emit:evolution-card","retain:lineage-evidence","block:unsafe-evolution"],"permissions":["read:local-mutation-fixtures"],"determinism":"byte_stable","autonomy_tier":"A1","boundary":BOUNDARY})}
fn validate_card(c:&EvolutionCard7)->Result<(),EvolutionIntegrityError>{if c.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||c.feature_id.is_empty()||c.request_id.is_empty()||c.purpose.is_empty()||c.boundary!=BOUNDARY||c.artifact.boundary!=BOUNDARY||!c.raw_data_local||!c.aggregate_only||!digest(&c.replay_identity)||!digest(&c.closure_digest)||c.artifact.content_type!=CONTENT_TYPE||c.artifact.content_hash!=c.closure_digest{return Err(invalid("evolution identity, locality, artifact, digest, or boundary is incomplete"));}for v in [&c.mutation_order,&c.accepted_order,&c.rejected_order,&c.unknown_order,&c.omitted_order,&c.parent_order,&c.effect_order,&c.lineage_order,&c.effect_receipts]{if !canonical(v){return Err(invalid("evolution vectors are not canonical"));}}let ids=c.mutation_order.iter().collect::<BTreeSet<_>>();let states=c.accepted_order.iter().chain(&c.rejected_order).chain(&c.unknown_order).chain(&c.omitted_order).collect::<Vec<_>>();if states.len()!=ids.len()||states.into_iter().collect::<BTreeSet<_>>()!=ids{return Err(invalid("mutation states do not partition candidates"));}Ok(())}
pub fn qualify(q:&EvolutionRequest4,feature_id:&str,contract_version:&str,scale:&str,mode:&str)->Result<EvolutionCard7,EvolutionIntegrityError>{if q.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||q.request_id.trim().is_empty()||q.purpose.trim().is_empty()||q.candidates.is_empty()||q.required_mutation_order.is_empty()||!canonical(&q.required_mutation_order)||!digest(&q.replay_identity)||q.boundary!=BOUNDARY||!q.raw_data_local||!q.aggregate_only||!canonical(&q.adversarial_events)||q.mutation_budget==0{return Err(invalid("evolution identity, ordering, digest, locality, boundary, or budget is invalid"));}let mut rows=q.candidates.clone();rows.sort_by(|a,b|a.mutation_id.cmp(&b.mutation_id));let mut seen=BTreeSet::new();let mut accepted=BTreeSet::new();let mut rejected=BTreeSet::new();let mut unknown=BTreeSet::new();let mut omitted=BTreeSet::new();let mut parents=BTreeSet::new();let mut effects=BTreeSet::new();let mut lineage=BTreeSet::new();let mut evidence=BTreeSet::new();for c in &rows{if c.mutation_id.trim().is_empty()||!seen.insert(c.mutation_id.clone())||c.parent_id.trim().is_empty()||c.parent_id==c.mutation_id||!digest(&c.digest)||c.effect_class.trim().is_empty()||c.evidence_state.trim().is_empty()||!c.local||!c.aggregate_only{return Err(invalid("mutation identity, parent, digest, effect, evidence, or locality is invalid"));}parents.insert(format!("{}:{}",c.mutation_id,c.parent_id));effects.insert(format!("{}:{}",c.mutation_id,c.effect_class));lineage.insert(format!("{}:{}",c.mutation_id,c.parent_id));evidence.insert(c.digest.clone());if c.evidence_state=="unknown"||c.digest==q.replay_identity{unknown.insert(c.mutation_id.clone());}else if c.effect_class=="unsafe"||c.effect_class=="unknown"{rejected.insert(c.mutation_id.clone());}else if !q.required_mutation_order.contains(&c.mutation_id){omitted.insert(c.mutation_id.clone());}else{accepted.insert(c.mutation_id.clone());}}let missing=q.required_mutation_order.iter().filter(|x|!seen.contains(*x)).cloned().collect::<Vec<_>>();let parent_missing=rows.iter().any(|c|c.parent_id!="root"&&!seen.contains(&c.parent_id));let global=!q.policy_allowed||!q.protected_closure||!q.signed_manifest||!q.raw_data_local||!q.aggregate_only||!q.adversarial_events.is_empty()||rows.len()>q.mutation_budget;if global{omitted.extend(seen.iter().cloned());accepted.clear();rejected.clear();unknown.clear();}let disposition=if global{"blocked"}else if !missing.is_empty()||parent_missing||!unknown.is_empty(){"unknown"}else if !rejected.is_empty()||!omitted.is_empty(){"partial"}else{"qualified"};let body=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":contract_version,"feature_id":feature_id,"request_id":q.request_id,"purpose":q.purpose,"disposition":disposition,"mutation_order":seen.iter().cloned().collect::<Vec<_>>()});let closure_digest=ContentHash::of_value(&body).map_err(|e|EvolutionIntegrityError::Digest(e.to_string()))?.to_string();let accepted_order=accepted.into_iter().collect::<Vec<_>>();let rejected_order=rejected.into_iter().collect::<Vec<_>>();let unknown_order=unknown.into_iter().collect::<Vec<_>>();let omitted_order=omitted.into_iter().collect::<Vec<_>>();let artifact=EvolutionArtifact4{artifact_id:format!("mutation-evolution:{}",q.request_id),content_type:CONTENT_TYPE.into(),content_hash:closure_digest.clone(),semantic_loss:omitted_order.clone(),evidence_digests:evidence.into_iter().collect(),boundary:BOUNDARY.into()};let c=EvolutionCard7{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:contract_version.into(),feature_id:feature_id.into(),request_id:q.request_id.clone(),purpose:q.purpose.clone(),disposition:disposition.into(),mutation_order:body["mutation_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),accepted_order,rejected_order,unknown_order,omitted_order,parent_order:parents.into_iter().collect(),effect_order:effects.into_iter().collect(),lineage_order:lineage.into_iter().collect(),replay_identity:q.replay_identity.clone(),closure_digest,raw_data_local:true,aggregate_only:true,boundary:BOUNDARY.into(),effect_receipts:if disposition=="qualified"{vec![format!("approve:evolution:{}",q.request_id)]}else{vec!["block:unsafe-evolution".into()]},artifact};validate_card(&c)?;let _=(scale,mode);Ok(c)}
